INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
('49549d3c-eeb3-4b8a-b44f-7767f36fa705', 'b4cf405b-8184-4a79-9706-e3622e9bd0e5', 'text', 'Nuestra Historia', 'APEDECA fue creada oficialmente el 21 de septiembre de 2012, inscrita en el Registro de Asociaciones de Canarias con el número G1/S1/19139-13/TF el 10 de abril de 2013.
INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
('7e3d264e-b4db-4208-b96f-651d3273efcf', 'b6d0447b-c80c-48d6-947d-c2bc4de0602d', 'text', 'Hazte voluntario', 'El voluntariado es una forma de compartir tu tiempo, tus conocimientos y tu compromiso con las personas con discapacidad y sus familias. En APEDECA encontrarás un espacio para participar, aprender y construir una sociedad más inclusiva.', NULL, 0, true, '2026-09-10T12:05:17.781003+00:00', '2026-09-10T12:05:17.781003+00:00');
