('156b6642-32ec-4ff9-a8f8-6b5790799a77', 'b1486128-a7fd-433e-b8b6-f5909c4cf35f', 'text', 'Nuestra Historia', 'APEDECA fue creada oficialmente el 21 de septiembre de 2012 e inscrita en el Registro de Asociaciones de Canarias con el número G1/S1/19139-13/TF el 10 de abril de 2013.
INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
('89256d6c-28fa-4361-9dfc-ab8026253f91', 'b4cf405b-8184-4a79-9706-e3622e9bd0e5', 'list', 'Nuestros compromisos', 'Cubrir las necesidades tanto de las personas con dependencia acogidos a La Ley de Promoción de la Autonomía Personal y Atención a las personas en situación de dependencia y a las familias de Canarias, ley 39/20006, desde los ámbitos autonómico y local, y en el marco de las Prestaciones Básicas de Servicios Sociales.
INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
('59c594f0-93cf-4c91-8f0a-35329a18b29e', 'd5604e48-990d-42fc-9d15-12d67d78af5b', 'text', 'Proyectos Recientes', 'Aquí encontrarás los proyectos más recientes en los que hemos trabajado. Estamos actualizando esta sección con los últimos proyectos en los que hemos participado, sus detalles y resultados.', NULL, 1, true, '2026-09-09T10:53:51.970344+00:00', '2026-09-09T10:53:51.970344+00:00');
INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
('080ebd24-eac2-4446-92fe-b11a5c52f05d', '3d2a6937-c584-4fdc-8f8c-6e8d86a72dde', 'text', 'Historial de Proyectos', 'Este es el archivo de proyectos en los que APEDECA ha participado o liderado a lo largo de los años. Un recorrido por nuestra trayectoria de compromiso con las personas dependientes en Canarias.', NULL, 1, true, '2026-09-09T10:53:51.970344+00:00', '2026-09-09T10:53:51.970344+00:00');
INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
('c1d2b099-7e73-4d6e-83d8-526abc8ee6ec', 'b6d0447b-c80c-48d6-947d-c2bc4de0602d', 'text', 'Oficina del voluntariado', 'A través del Cabildo de Tenerife y Sinpromi se gestiona esta oficina, en la que APEDECA está dada de alta desde el 29 de julio de 2013. Formamos parte de una amplia red de entidades que impulsan la participación y el apoyo a las personas con discapacidad.', NULL, 1, true, '2026-09-10T12:05:17.781003+00:00', '2026-09-10T12:05:17.781003+00:00');
INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
('38d4ff68-eafd-4795-88a0-3cf43836ab0f', 'b4cf405b-8184-4a79-9706-e3622e9bd0e5', 'button', 'Mantente informado', 'Visita nuestro portal de noticias', 'https://www.dependenciaencanarias.com/', 2, true, '2026-09-09T10:41:04.763288+00:00', '2026-09-09T10:41:04.763288+00:00');
INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
('a3410be8-54a8-4535-b159-54ac5df632f3', 'b6d0447b-c80c-48d6-947d-c2bc4de0602d', 'text', 'Cómo participar', 'Cuéntanos tus intereses, disponibilidad y experiencia. Juntos encontraremos la mejor forma de colaborar en nuestras actividades y proyectos.', NULL, 2, true, '2026-09-10T12:05:17.781003+00:00', '2026-09-10T12:05:17.781003+00:00');
INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
('ebed7c16-d3cb-4bc6-86f3-a3c8631da27d', 'b6d0447b-c80c-48d6-947d-c2bc4de0602d', 'volunteer-benefits', 'Programa desarrollado conforme a la Ley 4/1998 de Voluntariado de Canarias.', '[{"icon":"building","title":"Acreditado por el Gobierno de Canarias","detail":"Decreto 13/2020"},{"icon":"award","title":"Integrado en Sistema de Calidad","detail":"ISO 9001:2015"},{"icon":"badge","title":"Certificado oficial","detail":"de participación"},{"icon":"shield","title":"Seguro de voluntariado","detail":"incluido"},{"icon":"graduation","title":"Formación certificada","detail":"y seguimiento profesional"}]', NULL, 3, true, '2026-09-10T12:08:12.163373+00:00', '2026-09-10T12:08:12.163373+00:00');
INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
('0e4031d0-4e6c-46f7-8711-287a47f69190', 'b4cf405b-8184-4a79-9706-e3622e9bd0e5', 'areas', 'Áreas de Actuación', '[{"label":"ÁREA 1: Atención Psicosocial","title":"Atención Psicosocial","points":[]},{"label":"ÁREA 2: Integración y Ocio Inclusivo","title":"Integración y Ocio Inclusivo","points":[]},{"label":"ÁREA 3: Inserción Laboral y Formación","title":"Inserción Laboral y Formación","points":["Programas de inserción laboral","Formación profesional especializada","Creación de empleo para personas dependientes"]}]', NULL, 3, true, '2026-09-09T10:44:07.938516+00:00', '2026-09-09T10:44:07.938516+00:00');
INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
('a5640061-731c-4918-af24-2886c35089c2', 'b6d0447b-c80c-48d6-947d-c2bc4de0602d', 'volunteer-process', 'Proceso de incorporación', '{"steps":[{"side":"left","tone":"blue","title":"Contacto y Orientación Inicial","points":["Entrevista personal informativa","Presentación de proyectos y servicios","Evaluación de disponibilidad y motivación","Información sobre compromiso y responsabilidades"]},{"side":"right","tone":"green","title":"Formación Certificada Obligatoria","points":["Formación inicial especializada (presencial/online)","Talleres específicos según área de interés","Conocimiento de protocolos y procedimientos","Certificación de competencias básicas"]},{"side":"left","tone":"blue","title":"Integración y Seguimiento Profesional","points":["Asignación según perfil, intereses y necesidades","Acompañamiento por voluntario/a experimentado","Seguimiento continuo por equipo profesional","Evaluación periódica y formación continua"]}],"closing":"Buscamos personas comprometidas que puedan dedicar tiempo de manera regular, con flexibilidad horaria adaptada a las necesidades del servicio y disponibilidad personal."}', NULL, 4, true, '2026-09-10T12:20:00.553742+00:00', '2026-09-10T12:20:00.553742+00:00');
INSERT INTO cms_blocks (id, page_id, block_type, title, body, image_url, sort_order, is_visible, created_at, updated_at) VALUES
